-- Every payment drug and device makers gave doctors and hospitals in 2024 -- 15.4M records of industry money.
-- Auto-generated by scripts/gen_evidence_pages.py: 15,385,047 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("DATE_OF_PAYMENT") as year, count(*) as records
from THE_LIBRARY.HEALTH.PHARMA_PAYMENTS_TO_DOCTORS
where "DATE_OF_PAYMENT" is not null
group by 1
order by 1
